package com.hostelmanagement.controller;
import java.util.*; import jakarta.servlet.http.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final JdbcTemplate db; private final PasswordEncoder encoder;
 public AuthController(JdbcTemplate db,PasswordEncoder encoder){this.db=db;this.encoder=encoder;}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,String>b,HttpServletRequest r){String u=b.getOrDefault("username","").trim(),p=b.getOrDefault("password","");if(u.isBlank()||p.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter username and password.");var rows=db.queryForList("SELECT username,password_hash,role,warden_name,student_id FROM aishwarya.app_users WHERE username=?",u);if(rows.isEmpty()||!encoder.matches(p,String.valueOf(rows.get(0).get("password_hash"))))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password.");Map<String,Object>x=rows.get(0);String role=String.valueOf(x.get("role")).toUpperCase();if(!List.of("ADMIN","WARDEN","STUDENT").contains(role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Unsupported role.");HttpSession old=r.getSession(false);if(old!=null)old.invalidate();HttpSession s=r.getSession(true);s.setAttribute("username",u);s.setAttribute("userRole",role);s.setAttribute("wardenName",x.get("warden_name"));s.setAttribute("studentId",x.get("student_id"));return Map.of("username",u,"role",role,"message","Login successful.");}
 @GetMapping("/me") public Map<String,Object> me(HttpServletRequest r){var s=r.getSession(false);if(s==null||s.getAttribute("userRole")==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please log in.");Map<String,Object>m=new HashMap<>();m.put("username",s.getAttribute("username"));m.put("role",s.getAttribute("userRole"));return m;}
 @PostMapping("/logout") public Map<String,String> logout(HttpServletRequest r){var s=r.getSession(false);if(s!=null)s.invalidate();return Map.of("message","Logged out.");}
}
